"""Formatting helpers for tool-call evaluation reports and mismatch messages."""

from __future__ import annotations

from typing import Any

from rasa.builder.copilot.mcp_server.tools.expected_tools import (
    ExpectedTool,
    ExpectedToolGroup,
)
from rasa.shared.core.events import McpToolExecuted, ToolExecuted

_MAX_USER_MESSAGE_LEN = 200


def expected_tools_in_entry(
    entry: ExpectedTool | ExpectedToolGroup,
) -> list[ExpectedTool]:
    """Return the flat list of expected tools represented by one scenario entry."""
    if isinstance(entry, ExpectedToolGroup):
        return entry.tools
    return [entry]


def _format_tool_identity(tool_name: str, arguments: dict[str, Any] | None) -> str:
    """Render tool name and arguments without dispatch outcome."""
    if not arguments:
        return tool_name

    def arg_str(value: Any) -> str:
        if isinstance(value, bool):
            return "true" if value else "false"
        return repr(value)

    args = ", ".join(f"{name}={arg_str(value)}" for name, value in arguments.items())
    return f"{tool_name}({args})"


def format_tool(tool: ExpectedTool | McpToolExecuted | ToolExecuted) -> str:
    """Render an expected or observed MCP tool for reports and mismatch messages."""
    if isinstance(tool, ExpectedTool):
        return _format_tool_identity(tool.tool_name, tool.arguments)

    tool_name = (tool.tool_name or "").strip()
    arguments = dict(tool.arguments or {}) or None
    label = _format_tool_identity(tool_name, arguments)
    if tool.is_error:
        error_text = tool.error_message or "error"
        return f"{label} → ERROR: {error_text}"
    return label


def format_expected_tools_label(entry: ExpectedTool | ExpectedToolGroup) -> str:
    """Render all tools in one expected entry as a comma-separated label."""
    return ", ".join(format_tool(tool) for tool in expected_tools_in_entry(entry))


def format_assertion_label(entry: ExpectedTool | ExpectedToolGroup) -> str:
    """Render a short assertion label for a gated expected-tools entry."""
    kind = "tool_group" if isinstance(entry, ExpectedToolGroup) else "tool_called"
    return f"{kind}({format_expected_tools_label(entry)})"


from rasa.builder.copilot.mcp_server.tools.observed_tools import (  # noqa: E402
    ObservedTool,
    events_on_turn,
    turn_indices,
    user_message_for_turn,
)
from rasa.builder.copilot.mcp_server.tools.tool_scoring import (  # noqa: E402
    SCORE_METRICS,
    ToolScoresPerConversation,
    ToolScoresPerEntry,
    ToolScoringResult,
)


def _format_scope_header(scope: str, user_message: str = "") -> str:
    """Render a scope header, optionally including the user message."""
    if not user_message:
        return f"[{scope}]"
    truncated = (
        user_message
        if len(user_message) <= _MAX_USER_MESSAGE_LEN
        else user_message[: _MAX_USER_MESSAGE_LEN - 3] + "..."
    )
    return f'[{scope}] user: "{truncated}"'


def _format_turn_scope_header(
    turn_index: int | None,
    observed_tools: list[ObservedTool],
    *,
    scope_label: str | None = None,
) -> str:
    """Render a turn scope header for observed-only or per-entry report blocks."""
    if turn_index == 0:
        return "[pre-T1]  (events before first user turn)"
    if turn_index is None:
        return _format_scope_header(scope_label or "any turn")
    label = scope_label or f"T{turn_index}"
    return _format_scope_header(
        label, user_message_for_turn(turn_index, observed_tools)
    )


def _format_score_lines(score: ToolScoringResult, *, indent: str = "") -> list[str]:
    """Render precision, recall, and accuracy lines for one score object."""
    return [
        f"{indent}{name}: {value:.3f}"
        for name in SCORE_METRICS
        if (value := getattr(score, name)) is not None
    ]


def _format_gate_lines(
    tool_scoring: ToolScoresPerConversation,
    expected_tools: list[ExpectedTool | ExpectedToolGroup],
) -> list[str]:
    """Render gated ``expected_tools`` entries as assertion-style PASS/FAIL lines."""
    lines: list[str] = []
    for index, entry in enumerate(tool_scoring.per_entry):
        if not entry.gate:
            continue
        detail = (
            f"expected {format_expected_tools_label(expected_tools[index])}"
            if entry.gate_passed
            else entry.failure_reason or "accuracy below 1.0"
        )
        status = "PASS" if entry.gate_passed else "FAIL"
        lines.append(f"[{status}] {entry.assertion_label} — {detail}")
    return lines


def _format_per_entry_section(
    entry_score: ToolScoresPerEntry,
    expected_entry: ExpectedTool | ExpectedToolGroup,
    *,
    observed_tools: list[ObservedTool],
) -> list[str]:
    """Render one per-entry tool-scoring block for the run report."""
    turn = entry_score.matched_turn_index
    scope_label = f"matched T{turn}" if turn is not None else None
    observed = events_on_turn(turn, observed_tools) if turn is not None else []
    observed_lines = (
        ["  observed:", *(f"    {format_tool(event)}" for event in observed)]
        if observed
        else ["  observed: (none)"]
    )
    return [
        _format_turn_scope_header(turn, observed_tools, scope_label=scope_label),
        *_format_score_lines(entry_score, indent="  "),
        "  expected:",
        *(
            f"    {format_tool(tool)}"
            for tool in expected_tools_in_entry(expected_entry)
        ),
        *observed_lines,
        "",
    ]


def format_tool_scoring_report(
    tool_scoring: ToolScoresPerConversation | None,
    *,
    observed_tools: list[ObservedTool],
    expected_tools: list[ExpectedTool | ExpectedToolGroup],
) -> tuple[list[str], list[str]]:
    """Format tool-call metrics and gated assertion lines for the run report.

    Returns:
        A tuple of tool-metrics lines and gated assertion lines.
    """
    gate_lines = (
        _format_gate_lines(tool_scoring, expected_tools)
        if tool_scoring is not None
        else []
    )

    if tool_scoring is None:
        if not observed_tools:
            return ["(not defined)"], gate_lines
        metrics_lines: list[str] = []
        for turn_index in turn_indices(observed_tools):
            metrics_lines.append(_format_turn_scope_header(turn_index, observed_tools))
            metrics_lines.extend(
                f"  observed: {format_tool(event)}"
                for event in events_on_turn(turn_index, observed_tools)
            )
        return metrics_lines or ["(none called)"], gate_lines

    if not tool_scoring.per_entry:
        return ["(none defined)"], gate_lines

    metrics_lines = [
        "Conversation mean (across expected_tools entries):",
        *_format_score_lines(tool_scoring, indent="  "),
        "",
        "Per entry:",
    ]
    for entry_score, expected_entry in zip(
        tool_scoring.per_entry, expected_tools, strict=True
    ):
        metrics_lines.extend(
            _format_per_entry_section(
                entry_score,
                expected_entry,
                observed_tools=observed_tools,
            )
        )
    return metrics_lines, gate_lines
